using Microsoft.WSL.Containers;
using System.Text;
using System.Text.Json;
static void Emit(string stage, object details) { Console.WriteLine(JsonSerializer.Serialize(new { utc=DateTimeOffset.UtcNow, stage, details })); Console.Out.Flush(); }
if(args.Length!=8){Console.Error.WriteLine("usage: S12 <session> <storage> <image> <source> <wheels> <runner> <output> <container>");return 64;}
var sessionName=args[0]; var storagePath=Path.GetFullPath(args[1]); var image=args[2]; var sourcePath=Path.GetFullPath(args[3]); var wheelsPath=Path.GetFullPath(args[4]); var runnerPath=Path.GetFullPath(args[5]); var outputPath=Path.GetFullPath(args[6]); var containerName=args[7];
Directory.CreateDirectory(outputPath); var missing=WslcService.GetMissingComponents(); Emit("prerequisites",new {missing=missing.Select(x=>x.ToString()).ToArray()}); if(missing.Count!=0)return 65; var ver=WslcService.GetVersion(); Emit("version",new {ver.Major,ver.Minor,ver.Revision});
Session? session=null; Container? container=null; string? cid=null; Exception? failure=null; bool started=false,pulled=false,deleted=false,imageDeleted=false,terminated=false; int? exit=null; var stdout=new StringBuilder(); var stderr=new StringBuilder();
try {
 var settings=new SessionSettings(sessionName,storagePath){CpuCount=1,MemorySizeInMB=1536,Timeout=TimeSpan.FromMinutes(12),EnableGpu=false}; session=new Session(settings); session.Start(); started=true; Emit("session_started",new {sessionName,storagePath,cpu=1,memory_mb_requested=1536});
 var pull=session.PullImageAsync(new PullImageOptions(image)); pull.Progress+=(_,p)=>Emit("pull_progress",new {p.Status,p.Id,p.CurrentBytes,p.TotalBytes}); var pt=Task.Run(async()=>await pull); if(await Task.WhenAny(pt,Task.Delay(TimeSpan.FromMinutes(10)))!=pt){try{pull.Cancel();}catch{} throw new TimeoutException("pinned image pull timed out; state unknown");} await pt; pulled=true; Emit("image_pull_complete",new {image});
 var init=new ProcessSettings{CommandLine=new List<string>{"python","-B","/runner/run.py"},OutputMode=ProcessOutputMode.Event};
 var cs=new ContainerSettings(image){Name=containerName,InitProcess=init,NetworkingMode=ContainerNetworkingMode.None,EnableAutoRemove=false,EnableGpu=false,Privileged=false,Volumes=new List<ContainerVolume>{new(sourcePath,"/src",readOnly:true),new(wheelsPath,"/wheels",readOnly:true),new(runnerPath,"/runner",readOnly:true),new(outputPath,"/out",readOnly:false)}};
 container=session.CreateContainer(cs); cid=container.Id; var done=new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously); container.InitProcess.OutputReceived+=d=>{var s=Encoding.UTF8.GetString(d);lock(stdout)stdout.Append(s);Emit("container_stdout",new{text=s});}; container.InitProcess.ErrorReceived+=d=>{var s=Encoding.UTF8.GetString(d);lock(stderr)stderr.Append(s);Emit("container_stderr",new{text=s});}; container.InitProcess.Exited+=x=>done.TrySetResult(x); File.WriteAllText(Path.Combine(outputPath,"container.cid"),cid+"\n",Encoding.ASCII); Emit("container_created",new{cid,containerName,network="none",source_read_only=true,wheels_read_only=true,runner_read_only=true}); container.Start(); if(await Task.WhenAny(done.Task,Task.Delay(TimeSpan.FromSeconds(120)))!=done.Task)throw new TimeoutException("single test exceeded 120 seconds; outcome UNKNOWN"); exit=await done.Task; Emit("container_exited",new{cid,exit}); if(exit!=0)throw new InvalidOperationException("runner returned nonzero");
 using var report=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(outputPath,"result.json"))); if(report.RootElement.GetProperty("status").GetString()!="PASS_FAKE_X_STANDARD_CALLER_SCOPED")throw new InvalidOperationException("result status not pass");
} catch(Exception ex){failure=ex;Emit("failure",new{type=ex.GetType().FullName,message=ex.Message,hresult=ex.HResult,cid});}
finally {
 if(container is not null){try{if(container.State==ContainerState.Running)container.Stop(Signal.SIGTERM,TimeSpan.FromSeconds(10));container.Delete(DeleteContainerOption.Force);deleted=true;Emit("container_deleted",new{cid});}catch(Exception ex){failure??=ex;Emit("container_cleanup_failure",new{type=ex.GetType().FullName,message=ex.Message,cid});}finally{try{container.Dispose();}catch{}}}
 try{File.WriteAllText(Path.Combine(outputPath,"container.stdout.txt"),stdout.ToString(),new UTF8Encoding(false));File.WriteAllText(Path.Combine(outputPath,"container.stderr.txt"),stderr.ToString(),new UTF8Encoding(false));}catch(Exception ex){failure??=ex;}
 if(session is not null){if(pulled&&(container is null||deleted)){try{session.DeleteImage(image);imageDeleted=true;Emit("image_deleted",new{image});}catch(Exception ex){failure??=ex;Emit("image_cleanup_failure",new{type=ex.GetType().FullName,message=ex.Message});}} try{if(started){session.Terminate();terminated=true;Emit("session_terminated",new{sessionName});}}catch(Exception ex){failure??=ex;Emit("session_termination_failure",new{type=ex.GetType().FullName,message=ex.Message});}finally{try{session.Dispose();}catch{}}}
 File.WriteAllText(Path.Combine(outputPath,"resource-cleanup.json"),JsonSerializer.Serialize(new{sessionName,storagePath,started,terminated,image,pulled,imageDeleted,containerName,cid,deleted,exit,failure=failure is null?null:new{type=failure.GetType().FullName,message=failure.Message}},new JsonSerializerOptions{WriteIndented=true})+"\n",new UTF8Encoding(false));
}
return failure is null?0:1;
